    local function VM_0O0Il1(d, k, m)
        local R_O1lll = {}
        local c_key = k
        local char = string.char
        local insert = table.insert
        
        -- Virtual Machine Loop
        for idx = 1, #d do
            local val = d[idx]
            -- Decodificacao Rolling Key
            local dec = (val / m) - c_key
            
            -- Anti-Crash Mobile (Garante byte valido)
            dec = dec % 256
            
            insert(R_O1lll, char(dec))
            
            -- Atualiza a chave para o proximo (Rolling)
            c_key = (c_key + 13) % 150
        end
        return table.concat(R_O1lll)
    end

    -- Execution Guard
    local F_O101lOO1 = loadstring(VM_0O0Il1(B_1l1Ol00, 13, 5))
    if F_O101lOO1 then
        F_O101lOO1(...)
    end
end)(...)
